// Lead Form Component
const LeadForm = ({ variant = "hero" }) => {
  const [formData, setFormData] = useState({
    nome: "",
    cidade: "",
    telefone: ""
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.nome || !formData.cidade || !formData.telefone) {
      toast.error("Por favor, preencha todos os campos");
      return;
    }

    setIsSubmitting(true);

    try {
      const response = await fetch(`${API}/lead`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          nome: formData.nome,
          telefone: formData.telefone,
          cidade: formData.cidade,
          origem: "Site Alluz - Landing Page",
          utm_source: new URLSearchParams(window.location.search).get('utm_source') || 'direto',
          utm_medium: new URLSearchParams(window.location.search).get('utm_medium') || '',
          utm_campaign: new URLSearchParams(window.location.search).get('utm_campaign') || '',
        }),
      });

      if (response.ok) {
        if (typeof window !== "undefined" && typeof window.fbq === "function") {
          window.fbq("track", "Lead", {
            content_name: "Cadastro Landing Page",
            status: "completed",
          });
        }

        setIsSuccess(true);
        toast.success("Cadastro realizado com sucesso! Em breve entraremos em contato.");
        setFormData({ nome: "", cidade: "", telefone: "" });
        setTimeout(() => setIsSuccess(false), 5000);
      } else {
        toast.error("Erro ao enviar. Tente novamente.");
      }
    } catch (error) {
      console.error('Error:', error);
      toast.error("Erro ao enviar. Tente novamente.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const formatPhone = (value) => {
    const numbers = value.replace(/\D/g, '');
    if (numbers.length <= 2) return numbers;
    if (numbers.length <= 7) return `(${numbers.slice(0, 2)}) ${numbers.slice(2)}`;
    return `(${numbers.slice(0, 2)}) ${numbers.slice(2, 7)}-${numbers.slice(7, 11)}`;
  };

  const isHero = variant === "hero";

  return (
    <motion.form 
      onSubmit={handleSubmit}
      className={`${isHero ? 'glass-card p-6 md:p-8 rounded-3xl' : 'bg-white p-6 md:p-8 rounded-3xl shadow-2xl'}`}
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      viewport={{ once: true }}
      data-testid="lead-form"
    >
      {isSuccess ? (
        <motion.div 
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          className="text-center py-8"
        >
          <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-4" />
          <h3 className="text-xl font-bold text-gray-900 mb-2">Cadastro Realizado!</h3>
          <p className="text-gray-600">Em breve nossa equipe entrará em contato.</p>
        </motion.div>
      ) : (
        <>
          <div className="text-center mb-6">
            <h3 className={`text-xl md:text-2xl font-bold ${isHero ? 'text-gray-900' : 'text-gray-900'}`}>
              Receba sua análise gratuita
            </h3>
            <p className={`text-sm mt-2 ${isHero ? 'text-gray-600' : 'text-gray-600'}`}>
              Sem compromisso. Descubra quanto você pode economizar.
            </p>
          </div>

          <div className="space-y-4">
            <div>
              <Label htmlFor={`nome-${variant}`} className="text-gray-700 font-medium">
                Nome completo
              </Label>
              <div className="relative mt-1">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <Input
                  id={`nome-${variant}`}
                  type="text"
                  placeholder="Seu nome"
                  value={formData.nome}
                  onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                  className="pl-10 h-12 bg-gray-50 border-gray-200 focus:border-amber-500 focus:ring-amber-500/20 rounded-xl"
                  data-testid={`input-nome-${variant}`}
                />
              </div>
            </div>

            <div>
              <Label htmlFor={`cidade-${variant}`} className="text-gray-700 font-medium">
                Cidade
              </Label>
              <div className="relative mt-1">
                <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <Input
                  id={`cidade-${variant}`}
                  type="text"
                  placeholder="Sua cidade"
                  value={formData.cidade}
                  onChange={(e) => setFormData({ ...formData, cidade: e.target.value })}
                  className="pl-10 h-12 bg-gray-50 border-gray-200 focus:border-amber-500 focus:ring-amber-500/20 rounded-xl"
                  data-testid={`input-cidade-${variant}`}
                />
              </div>
            </div>

            <div>
              <Label htmlFor={`telefone-${variant}`} className="text-gray-700 font-medium">
                Telefone / WhatsApp
              </Label>
              <div className="relative mt-1">
                <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <Input
                  id={`telefone-${variant}`}
                  type="tel"
                  placeholder="(00) 00000-0000"
                  value={formData.telefone}
                  onChange={(e) => setFormData({ ...formData, telefone: formatPhone(e.target.value) })}
                  className="pl-10 h-12 bg-gray-50 border-gray-200 focus:border-amber-500 focus:ring-amber-500/20 rounded-xl"
                  data-testid={`input-telefone-${variant}`}
                />
              </div>
            </div>

            <Button
              type="submit"
              disabled={isSubmitting}
              className="w-full h-14 bg-amber-500 hover:bg-amber-600 text-black font-bold text-lg rounded-full transition-all hover:scale-[1.02] active:scale-[0.98] pulse-glow disabled:opacity-50"
              data-testid={`submit-form-${variant}`}
            >
              {isSubmitting ? (
                <span className="flex items-center gap-2">
                  <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/>
                  </svg>
                  Enviando...
                </span>
              ) : (
                <span className="flex items-center justify-center gap-2">
                  Quero Minha Análise Gratuita
                  <ArrowRight className="w-5 h-5" />
                </span>
              )}
            </Button>
          </div>

          <p className="text-xs text-gray-500 text-center mt-4">
            Seus dados estão seguros. Não compartilhamos com terceiros.
          </p>
        </>
      )}
    </motion.form>
  );
};

